head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > checkcomboboxVisibleRowNum]<br/>inputType='checkcombobox' 인 Column 에서 아이템 리스트창에 한번에 표시할 아이템의 갯수를 설정합니다.",
    "validation" : [
        "아이템 리스트창에 한번에 표시할 아이템의 갯수를 설정합니다.",
        "0 을 설정할 경우 아이템 리스트창이 정상적으로 표시되지 않으므로 2 이상의 적절한 값으로 설정해야 합니다.",
        "속성값을 설정하지 않으면 5 로 적용됩니다.",
        "아이템 전체 갯수가 checkcomboboxVisibleRowNum 속성값보다 큰 경우 아이템 리스트창에 세로 스크롤이 표시됩니다.",
        "아이템이 GridViewItemSet 으로 정의된 경우 설정 팝업창의 'Style Property' 탭에 설정한 'VisibleRowNum' 값이 우선 적용됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (RowNum=3, 아이템 8개, Item 정의)
    con_checkcomboboxVisibleRowNum.setValue("3");
    con_itemCount.setValue("8");
    con_itemDefinition.setValue("item");
    con_itemsetVisibleRowNum.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name : 아이템 갯수 표시 Column (readOnly)
//  - code : 검증 대상 Body Column (inputType=checkcombobox, 아이템 1 ~ N)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_code !== 'undefined' && dlt_code) {
        $p.data.remove("dlt_code");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] code 셀 더블클릭으로 아이템 리스트창 열기\n[확인] 결과창의 세로 스크롤 여부와 리스트창에 한번에 표시된 행별 아이템\nVisibleRowNum (GridViewItemSet) 옵션은 아이템 정의가 GridViewItemSet 일 때만 적용"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cRowNum = con_checkcomboboxVisibleRowNum.getValue();
    let cItemCount = Number(con_itemCount.getValue());
    let cItemDefinition = con_itemDefinition.getValue();
    let cItemsetRowNum = con_itemsetVisibleRowNum.getValue();
    scwin.itemCount = cItemCount;

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "아이템 " + cItemCount + "개", "code" : "" }
    ], false);

    // 아이템 정의 (label / value : 1 ~ N)
    let strItems = '<w2:choices>';
    if (cItemDefinition === "gridViewItemset") {
        // GridViewItemSet : checkbox item 은 dataList 첫 컬럼(chk) 을 참조 (checkColumn=0)
        let strItemDlt = '';
        strItemDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_code" baseNode="list" repeatNode="map">';
        strItemDlt += '<w2:columnInfo>';
        strItemDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
        strItemDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
        strItemDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
        strItemDlt += '</w2:columnInfo>';
        strItemDlt += '<w2:data use="true"></w2:data>';
        strItemDlt += '</w2:dataList>';
        $p.data.create(strItemDlt);
        let arrItem = [];
        for (let i = 1; i <= cItemCount; i++) {
            arrItem.push({ "chk" : "0", "value" : String(i), "label" : String(i) });
        }
        dlt_code.setJSON(arrItem, false);

        // 설정 팝업창 Style Property 탭의 VisibleRowNum = gridViewItemset 노드의 visibleRowNum 속성
        let attrItemset = (cItemsetRowNum === '') ? '' : ' visibleRowNum="' + cItemsetRowNum + '"';
        strItems += '<w2:gridViewItemset nodeset="data:dlt_code" label="label" value="value" checkColumn="0"' + attrItemset + '>';
        strItems += '<w2:item header="선택" inputType="checkbox" ref="chk"></w2:item>';
        strItems += '<w2:item header="value" ref="value"></w2:item>';
        strItems += '<w2:item header="label" ref="label"></w2:item>';
        strItems += '</w2:gridViewItemset>';
    } else {
        for (let i = 1; i <= cItemCount; i++) {
            strItems += '<w2:item><w2:label>' + i + '</w2:label><w2:value>' + i + '</w2:value></w2:item>';
        }
    }
    strItems += '</w2:choices>';

    // code Column 속성
    let attrCode = ' inputType="checkcombobox"';
    attrCode += (cRowNum === '') ? '' : ' checkcomboboxVisibleRowNum="' + cRowNum + '"';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:120px;" ev:oncelldblclick="scwin.target1_oncelldblclick">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="아이템 구성"></w2:column>';
    strTarget += '<w2:column width="380" style="" inputType="text" id="column2" value="code (checkcombobox)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="380" style="text-align:left;" id="code" value=""' + attrCode + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 ~ 5 : code 셀 더블클릭으로 리스트창이 열린 뒤 아이템 리스트창 구성 출력
scwin.target1_oncelldblclick = function (rowIndex, colIndex, columnId) {
    if (columnId !== "code") {
        return;
    }
    setTimeout(function () {
        scwin.printItemList();
    }, 300);
}



// 아이템 리스트창 구성 출력
//  - 첫 줄 : 아이템 갯수와 세로 스크롤 여부 (validation 4) / GridViewItemSet 이면 GridView 팝업창의 세로 스크롤 여부 (validation 5)
//  - 이후 : 리스트창에 한번에 표시된(스크롤 없이 보이는) 행마다 아이템 라벨 (validation 1, 2, 3, 5)
scwin.printItemList = function () {
    let strPrefix = "G_" + target1.id + "___checkcombobox_code";
    let gridItemTable = document.querySelector("div[id='" + strPrefix + "_gridViewItemTable']");
    if (gridItemTable && gridItemTable.offsetHeight > 0) {
        scwin.printGridViewItemList(gridItemTable);
        return;
    }

    let itemTable = document.querySelector("div[id='" + strPrefix + "_itemTable']");
    if (!itemTable || itemTable.offsetHeight === 0) {
        return;
    }
    let bScroll = itemTable.scrollHeight > itemTable.clientHeight;
    wf_body_bottom.getObj("scwin").setReturnValue("아이템 " + scwin.itemCount + "개 -> 세로 스크롤 : " + bScroll);

    let rows = itemTable.querySelectorAll("table[id='" + strPrefix + "_itemTable_main'] tr");
    let nBottom = itemTable.getBoundingClientRect().top + itemTable.clientHeight;
    for (let i = 0; i < rows.length; i++) {
        // 리스트창 높이 안에 온전히 보이는 행만 출력
        if (rows[i].getBoundingClientRect().bottom > nBottom + 1) {
            break;
        }
        let arrLabel = Array.prototype.map.call(rows[i].querySelectorAll("td[data-index]"), function (td) {
            return td.textContent;
        });
        wf_body_bottom.getObj("scwin").setReturnValue((i + 1) + "행 : " + arrLabel.join(", "));
    }
}



// GridView 팝업창 구성 출력 (GridViewItemSet : validation 5)
//  - 첫 줄 : GridView 팝업창의 세로 스크롤 여부
//  - 이후 : GridView 팝업창에 한번에 표시된 행마다 label 컬럼 값
scwin.printGridViewItemList = function (gridItemTable) {
    let scrollY = gridItemTable.querySelector("div[id$='_gridView_scrollY_div']");
    let bScroll = !!scrollY && scrollY.scrollHeight > scrollY.offsetHeight;
    wf_body_bottom.getObj("scwin").setReturnValue("아이템 " + scwin.itemCount + "개 -> GridView 팝업창 세로 스크롤 : " + bScroll);

    let nRow = 0;
    while (true) {
        let td = gridItemTable.querySelector("td[id$='_gridView_cell_" + nRow + "_2']");
        if (!td || td.offsetHeight === 0) {
            break;
        }
        nRow++;
        wf_body_bottom.getObj("scwin").setReturnValue(nRow + "행 : " + td.textContent);
    }
}
